import std::mem;

// Allocate zeroed counters for code that will fill them later.
fn createCounters(count: usize) ptr @public {
    return mem::allocateZeroedMemory(count, sizeOf(s32));
}

fn destroyCounters(counters: ptr) void @public {
    if counters != nullptr {
        mem::freeMemory(counters);
    }
}

import std::mem;

// Compare a small binary header without copying it into a struct first.
fn sameHeader(left: ptr, right: ptr) bool @public {
    return mem::compareMemory(left, right, 16) == 0;
}

fn containsTerminator(buffer: ptr, length: usize) bool @public {
    return mem::findByteInMemory(buffer, 0, length) != nullptr;
}

