import std::ffi::c::mem as c;

// Wrap raw allocation so callers have one place to check for nullptr.
fn allocateScratch(size: usize) ptr @public {
    var block: ptr = c::calloc(1, size);

    if block == nullptr {
        return nullptr;
    }

    return block;
}

