import std::ffi::c::int as c;

// atoi is raw and simple. Wrap it when the surrounding code only needs a
// small, trusted decimal value.
fn readWorkers(text: CString) s32 @public {
    var workers: s32 = c::atoi(text);

    if workers < 1 {
        return 1;
    }

    return workers;
}

import std::ffi::c::int as c;

// strtol lets the wrapper choose the numeric base at the boundary.
fn parsePort(text: CString) s32 @public {
